var ARTICLES=[
 {n:1,mono:'m-gray',dot:'green',sec:'res',h:"Strumentazione paziente-specifica in protesi monocompartimentale: nessun vantaggio funzionale",v:"revisione sistematica di 14 studi, 1.680 ginocchia: nessuna differenza significativa nell'Oxford Knee Score a un anno fra strumentazione paziente-specifica e convenzionale (differenza media 0,90; IC 95% -2,65/4,45; I²=0%); dati di revisione troppo eterogenei per un confronto aggregato",ax:"Ruhle … Alvand",date:"ago 2026",meta:"revisione sistematica e meta-analisi · 14 studi, 1.680 ginocchia (5 RCT + 9 retrospettivi) · [II-III]",pmid:'42641204',doi:'10.1016/j.knee.2026.104608',journal:"The Knee",authors:"Ruhle V, Rudran B, Leung B, Merle C, Murray D, Price A, Alvand A",design:"Revisione sistematica e meta-analisi (PRISMA; Embase, MEDLINE, Cochrane Library) di studi comparativi fra strumentazione paziente-specifica (PSI) e convenzionale in protesi monocompartimentale di ginocchio (UKA) primaria. Rischio di bias valutato con RoB 2 e ROBINS-I.",pop:"14 studi, 1.680 ginocchia in 1.670 pazienti: 5 studi randomizzati controllati a basso rischio di bias e 9 studi retrospettivi comparativi, con rischio di bias da moderato ad alto in diversi casi.",results:"Oxford Knee Score a 1 anno: nessuna differenza significativa fra PSI e strumentazione convenzionale (differenza media 0,90; IC 95% -2,65/4,45; I²=0%). Knee Society Score e Knee injury and Osteoarthritis Outcome Score a 3 mesi e a ≥12 mesi: nessuna differenza significativa fra i gruppi. Dati WOMAC insufficienti per la meta-analisi. Dati di revisione protesica eterogenei fra gli studi, non idonei alla sintesi quantitativa.",concl:"Gli autori concludono che la PSI non dimostra risultati funzionali post-operatori superiori rispetto alla strumentazione convenzionale in UKA; l'effetto sul rischio di revisione resta incerto per l'eterogeneità e la limitatezza dei dati disponibili.",limits:"Dati di revisione protesica troppo eterogenei per la sintesi quantitativa: non risolvono la domanda sulla sopravvivenza dell'impianto · mix di 5 RCT a basso rischio di bias e 9 studi retrospettivi con rischio da moderato ad alto · WOMAC non utilizzabile per insufficienza dei dati riportati",perte:"Tocca la scelta strumentale nella tua chirurgia monocompartimentale: la strumentazione paziente-specifica, spesso proposta come miglioria tecnologica, non mostra oggi un vantaggio funzionale dimostrato rispetto a quella convenzionale nella finestra fino a un anno. Non è un argomento per abbandonarla se già la usi, né per adottarla se non la usi: è un argomento contro l'idea che sia necessaria per ottenere buoni risultati funzionali. La domanda sulla sopravvivenza dell'impianto resta aperta."},
 {n:2,mono:'m-gray',dot:'green',sec:'res',h:"Nella ricostruzione del LCA il fallimento dell'innesto non dipende dalla larghezza del notch",v:"coorte retrospettiva di 452 ricostruzioni: età più giovane (OR 0,91; IC 95% 0,84-1,00) e diametro tibiale dell'innesto più piccolo (OR 0,48; IC 95% 0,23-1,00) si associano al fallimento (4,2% complessivo), non l'indice di larghezza del notch (p=0,237); nessun fallimento fra i 18 pazienti con LET concomitante, campione troppo piccolo per dirlo con certezza",ax:"Nicholas … Brown",date:"ago 2026",meta:"coorte retrospettiva · 452 pz · [III]",pmid:'42641205',doi:'10.1016/j.knee.2026.104610',journal:"The Knee",authors:"Nicholas PRM, Ulla S, Rankin CS, Young D, Davidson L, Spencer SJ, Brown MJC",design:"Revisione retrospettiva di 452 ricostruzioni primarie del LCA (2012-2024). Indice di larghezza del notch intercondiloideo (NWI) misurato su RM coronale preoperatoria, con affidabilità interosservatore valutata (ICC). Fallimento dell'innesto definito come revisione chirurgica. Analisi univariata e multivariabile per i fattori di rischio.",pop:"452 pazienti sottoposti a ricostruzione primaria del LCA fra il 2012 e il 2024. Affidabilità interosservatore per la misura del NWI alta (ICC 0,865). Diciotto pazienti con tenodesi extra-articolare laterale (LET) concomitante.",results:"19 fallimenti dell'innesto su 452 (4,2%). Il NWI non è risultato associato al fallimento (p=0,237). Nemmeno il sesso (p=0,483) né il tipo di innesto (p=0,536) sono risultati associati. Età più giovane (p=0,008) e diametro tibiale dell'innesto più piccolo (p=0,049) sono risultati associati al fallimento. All'analisi multivariabile: età più giovane (OR 0,91; IC 95% 0,84-1,00) e diametro dell'innesto più piccolo (OR 0,48; IC 95% 0,23-1,00) fattori indipendenti. Nessun fallimento registrato fra i 18 pazienti con LET concomitante (0/18): confrontato con il resto della coorte (19/434, 4,4%), il rischio relativo ricalcolato con `test/potenza.py` è 0,59, con un intervallo di confidenza al 95% da 0,04 a 9,36 — non esclude né una forte protezione né un rischio quasi decuplicato.",concl:"Gli autori concludono che il NWI non è un fattore di rischio significativo per il fallimento dell'innesto dopo ricostruzione del LCA; età più giovane e diametro dell'innesto più piccolo sono i fattori indipendenti identificati, e suggeriscono di considerare innesti di calibro adeguato insieme a procedure aggiuntive come il LET nei pazienti selezionati ad alto rischio.",limits:"Sottogruppo LET concomitante piccolissimo (18 pazienti, zero eventi): dimensione dell'effetto e intervalli di confidenza non riportati nell'abstract per questo confronto, dato muto ricalcolato qui (RR 0,59; IC 95% 0,04-9,36) · disegno retrospettivo monocentrico, nessuna randomizzazione all'aggiunta del LET · fallimento definito come sola revisione chirurgica, non include lassità residua sintomatica non rioperata",perte:"Riguarda direttamente la tua indicazione universale al LET: in questa coorte, nessuno dei 18 pazienti operati con LET concomitante ha avuto un fallimento dell'innesto, mentre il resto della coorte ne ha avuti il 4,4%. È un segnale nella direzione che segui, ma il campione è troppo piccolo per dimostrarlo — l'intervallo di confidenza ricalcolato non esclude né un forte beneficio né un rischio quasi decuplicato. Il dato più solido dello studio, comunque, è un altro: il diametro dell'innesto conta più della morfologia del notch, un argomento per non sottodimensionare l'innesto nei pazienti più giovani ad alto rischio."},
 {n:3,mono:'m-gray',dot:'green',sec:'res',h:"L'infezione dopo ricostruzione del LCA aumenta il rischio di artrosi a lungo termine",v:"studio caso-controllo a 16,2 anni di follow-up medio: tutti e 7 i pazienti con infezione postoperatoria hanno sviluppato artrosi in tutti e tre i compartimenti, contro il 35% del gruppo di controllo appaiato (p=0,0058); campione degli infetti minimo, ma il segnale raggiunge la significatività statistica",ax:"Akrivos … Hantes",date:"ago 2026",meta:"studio caso-controllo appaiato · 7 casi vs coorte di controllo · [III]",pmid:'42638194',doi:'10.1002/arj.70489',journal:"Arthroscopy",authors:"Akrivos VS, Koskiniotis A, Konstantinou E, Metaxiotis N, Saridis A, Stefanou N, Hantes M",design:"Studio retrospettivo caso-controllo che confronta gli esiti radiografici e clinici a lungo termine di pazienti con infezione postoperatoria dopo ricostruzione primaria del LCA (2003-2014) con un gruppo appaiato senza complicanze infettive. Follow-up minimo 10 anni, artrosi radiografica valutata con i criteri Kellgren-Lawrence e OARSI.",pop:"Sette pazienti con infezione postoperatoria dopo ACLR primaria, nessuna artrosi al basale, confrontati con un gruppo di controllo appaiato senza complicanze. Follow-up medio 16,2 anni (range 14-19).",results:"Tutti e 7 i pazienti con infezione (100%) hanno sviluppato artrosi in tutti e tre i compartimenti (Kellgren-Lawrence ≥2) all'ultimo controllo, contro il 35% del gruppo di controllo (p=0,0058). Angolo anca-ginocchio-caviglia: 4,42° di varismo negli infetti contro 4,67° nei controlli (p=0,77, nessuna differenza). Nessuna differenza significativa nei punteggi clinici (IKDC, Lysholm, Tegner), nella lassità antero-posteriore al KT-1000 né nel ginocchio controlaterale fra i due gruppi.",concl:"Gli autori concludono che l'infezione postoperatoria dopo ACLR aumenta in modo significativo il rischio di artrosi a tre compartimenti a lungo termine rispetto a una ricostruzione senza complicanze, pur senza differenze nei punteggi clinici funzionali riferiti a distanza.",limits:"Solo 7 pazienti nel gruppo infetto: numero assoluto minimo, anche se il confronto raggiunge la significatività statistica (p=0,0058) per l'ampiezza dell'effetto (100% vs 35%) · dimensione del gruppo di controllo non dichiarata nell'abstract · nessuna distinzione per germe responsabile, tempestività del trattamento o numero di reinterventi per bonificare l'infezione",perte:"Non tocca il tuo innesto o la tua tecnica specificamente, ma è un promemoria diretto sul peso della complicanza infettiva dopo ricostruzione del LCA: a differenza di quanto la sola clinica funzionale suggerirebbe (nessuna differenza nei punteggi soggettivi a distanza), il danno cartilagineo radiografico a lungo termine è marcatamente maggiore. Un argomento in più per la profilassi e per il colloquio informativo sui rischi, anche quando l'infezione viene trattata con successo e il ginocchio 'funziona' bene."},
 {n:4,mono:'m-gray',dot:'green',sec:'res',h:"Osteomielite fungina dopo sutura della radice meniscale: primo caso descritto",v:"caso clinico: donna di 70 anni con osteomielite subacuta da Aspergillus versicolor mesi dopo rifissazione artroscopica della radice meniscale mediale, risolta con debridement, rimozione della sutura ritenuta e voriconazolo orale; a un anno nessun segno di infezione residua",ax:"Magoline … Magoline",date:"ago 2026",meta:"caso clinico · 1 paziente · [V]",pmid:'42627949',doi:'10.2106/JBJS.CC.25.00493',journal:"JBJS Case Connector",authors:"Magoline JA, Polousky JD, Magoline SA",design:"Caso clinico singolo: donna di 70 anni con dolore tibiale subacuto e secrezione ricorrente insorti mesi dopo rifissazione artroscopica della radice meniscale mediale posteriore (MRR).",pop:"Un caso, donna di 70 anni.",results:"RM: ascesso metafisario tipo Brodie originante dal portale antero-mediale. PCR sul materiale prelevato: Aspergillus versicolor. Trattamento: debridement chirurgico con rimozione della sutura ritenuta, seguito da voriconazolo orale. Al controllo a un anno: nessun segno di infezione residua, ritorno all'esercizio fisico senza dolore. Caso singolo, nessun dato numerico aggregato: nessun denominatore né confronto.",concl:"Gli autori concludono che questo rappresenta, per quanto a loro noto, il primo caso descritto di osteomielite fungina dopo rifissazione della radice meniscale, e che i pazienti anziani possono avere un rischio aumentato di infezioni profonde rare e atipiche dopo questo intervento; i chirurghi che considerano la MRR nell'anziano dovrebbero esserne consapevoli.",limits:"Caso singolo: nessuna incidenza calcolabile, nessun denominatore · nessun fattore predisponente sistemico (immunosoppressione, diabete) riportato nell'abstract come possibile spiegazione della suscettibilità fungina · nesso causale con la tecnica chirurgica, piuttosto che con l'ospite, non dimostrabile da un singolo caso",perte:"Tocca direttamente la tua tecnica di rifissazione transtibiale della radice meniscale: è una complicanza rarissima e non generalizzabile da un solo caso, ma la localizzazione — ascesso che origina dal portale antero-mediale, con sutura ritenuta come possibile nido dell'infezione — è specifica del gesto artroscopico che fai. Non cambia l'indicazione, ma è un promemoria utile sulla soglia di sospetto per un dolore atipico e persistente mesi dopo un intervento apparentemente riuscito, specie nella paziente anziana."}
];
var SUGGQ=[{k:"kol",n:"Michael Hantes",w:"Department of Orthopaedic Surgery and Musculoskeletal Trauma, Faculty of Medicine, School of Health Sciences, University of Thessalia, Larissa, Grecia",r:"Autore senior dello studio di oggi sull'infezione dopo ricostruzione del LCA e il rischio di artrosi a lungo termine: corrispondenza tecnica diretta con la tua chirurgia del legamento crociato anteriore e con l'attenzione alle complicanze a lungo termine."}];
var BRIEF_TEXT="Buongiorno. Oggi quattro schede. Il lavoro del giorno riguarda la ricostruzione del legamento crociato anteriore: una coorte retrospettiva di quattrocentocinquantadue pazienti mostra che il fallimento dell'innesto non dipende, come si pensava, dalla larghezza del canale osseo del notch, ma dall'età più giovane e da un innesto tibiale di calibro più piccolo. Un dettaglio tocca direttamente la tua pratica: fra i diciotto pazienti operati anche con la tenodesi laterale, nessuno ha avuto un fallimento — ma il gruppo è troppo piccolo per dimostrare che sia merito del rinforzo, l'intervallo di confidenza ricalcolato non esclude né un forte beneficio né un rischio quasi decuplicato, ed è quello che ho aggiunto alla tensione sul rinforzo laterale che segui da settimane. La seconda scheda riguarda la protesi monocompartimentale: una revisione di quattordici studi non trova alcun vantaggio funzionale della strumentazione costruita su misura del paziente rispetto a quella convenzionale a un anno. La terza è un promemoria sul peso dell'infezione dopo la ricostruzione del crociato: a sedici anni di distanza, tutti e sette i pazienti che avevano avuto un'infezione avevano sviluppato artrosi in tutta l'articolazione, contro poco più di un terzo dei controlli, anche se i punteggi di funzione a distanza erano simili — campione minimo, ma l'effetto è ampio. L'ultima scheda è un caso clinico raro: la prima osteomielite fungina mai descritta dopo la rifissazione della radice meniscale, risolta con successo in una paziente di settant'anni. Il raccoglitore automatico è passato regolarmente questa notte: nessun richiamo nuovo sui due dispositivi che sorvegli, nessuna ritrattazione fra i centodiciannove DOI citati controllati via Crossref, e nessun nuovo citante per gli otto PICK di cui teniamo il destino. Ho fatto ricontrollare anche di persona su PubMed le ritrattazioni sull'intero perimetro citato, ottantotto lavori dello storico più i quattro di oggi: stesso esito, nessuna ritrattazione né espressione di dubbio. Nella seconda pagina quattordici brevi di oggi, soprattutto temi perioperatori di protesi e dintorni del crociato anteriore, e tre proposte fuori dal solito: uno studio cinese di agopuntura sui punti trigger per l'artrosi, la lettura dell'attività cerebrale per distinguere i tipi di dolore da artrosi, e un'intelligenza artificiale che stima il carico articolare senza pedana di forza nei bambini con paralisi cerebrale. Per oggi è tutto.";
var BRIEF_DIALOGO=[
{chi:"A",t:"Buongiorno. Oggi quattro schede, e quella del giorno tocca proprio la tua tenodesi laterale."},
{chi:"B",t:"Ah sì? In che senso?"},
{chi:"A",t:"Una coorte di 452 pazienti operati di crociato anteriore cerca i motivi del fallimento dell'innesto. Il canale osseo del notch, che si sospettava, non conta. Contano l'età più giovane e un innesto più sottile."},
{chi:"B",t:"E il rinforzo laterale?"},
{chi:"A",t:"Fra i diciotto pazienti che l'hanno avuto in aggiunta, zero fallimenti. Ma il gruppo è piccolissimo: l'intervallo di confidenza, ricalcolato, non esclude né un forte beneficio né un rischio quasi decuplicato."},
{chi:"B",t:"Quindi resta un segnale, non una prova."},
{chi:"A",t:"Esatto, e l'ho aggiunto alla tensione che segui già da settimane. Il dato più solido dello studio è un altro: conta il diametro dell'innesto, non la forma del ginocchio."},
{chi:"B",t:"E le altre tre schede?"},
{chi:"A",t:"La protesi monocompartimentale su misura del paziente non batte quella convenzionale a un anno, in una revisione di 14 studi. Poi un promemoria sull'infezione dopo il crociato: a 16 anni, chi l'ha avuta ha molta più artrosi diffusa, anche se il ginocchio funziona bene."},
{chi:"B",t:"E la quarta?"},
{chi:"A",t:"Un caso raro: la prima infezione fungina mai descritta dopo la sutura della radice meniscale, risolta bene in una signora di settant'anni."},
{chi:"B",t:"Devo saperlo per la mia pratica del root repair?"},
{chi:"A",t:"È un caso singolo, non cambia l'indicazione — ma tienilo a mente se un dolore atipico persiste mesi dopo un intervento che sembrava riuscito."},
{chi:"B",t:"E il raccoglitore stanotte?"},
{chi:"A",t:"È passato regolarmente. Nessun richiamo nuovo, nessuna ritrattazione su centodiciannove DOI controllati, nessun nuovo citante per i PICK sorvegliati. E le ritrattazioni le ho ricontrollate anche io di persona: nessuna, su tutto lo storico."},
{chi:"B",t:"Va bene, per oggi è tutto allora."}
];
