var DUELS=[];var HISTORY=[{d:'2026-08-02',label:'domenica 2 agosto',n:11,rossi:0,arancioni:2,pick:2},{d:'2026-08-04',label:'martedì 4 agosto',n:9,rossi:0,arancioni:1,pick:1},{d:'2026-08-06',label:'giovedì 6 agosto',n:6,rossi:0,arancioni:0,pick:1},{d:'2026-08-07',label:'venerdì 7 agosto',n:7,rossi:0,arancioni:1,pick:1},{d:'2026-08-09',label:'domenica 9 agosto',n:9,rossi:0,arancioni:1,pick:2},{d:'2026-08-12',label:'mercoledì 12 agosto',n:10,rossi:0,arancioni:1,pick:1},{d:'2026-08-17',label:'lunedì 17 agosto',n:10,rossi:0,arancioni:0,pick:1},{d:'2026-08-18',label:'martedì 18 agosto',n:6,rossi:0,arancioni:0,pick:1},{d:'2026-08-19',label:'mercoledì 19 agosto',n:8,rossi:0,arancioni:0,pick:3},{d:'2026-08-20',label:'giovedì 20 agosto',n:9,rossi:0,arancioni:0,pick:1},{d:'2026-08-21',label:'venerdì 21 agosto',n:9,rossi:0,arancioni:2,pick:1},{d:'2026-08-22',label:'sabato 22 agosto',n:6,rossi:0,arancioni:0,pick:1},{d:'2026-08-23',label:'domenica 23 agosto',n:5,rossi:0,arancioni:1,pick:1},{d:'2026-08-24',label:'lunedì 24 agosto',n:1,rossi:0,arancioni:1,pick:1},{d:'2026-08-25',label:'martedì 25 agosto',n:4,rossi:0,arancioni:0,pick:1},{d:'2026-08-26',label:'mercoledì 26 agosto',n:4,rossi:0,arancioni:0,pick:2}];
var AUDIT={settimana:"26 agosto 2026",visti:55,scartati:"circa 34 candidati esaminati almeno per titolo/abstract e scartati: fuori perimetro (un acronimo HTO omonimo in uno studio di geologia, radiologia interventistica pediatrica non ortopedica, microCT su ginocchio murino — biologia di base) · articoli in lingua cinese di rilevanza locale marginale rispetto alla rete di riferimento dichiarata (consensus su percorso clinico ERAS in protesi di ginocchio, note tecniche su artroplastica robotica con riferimenti anatomici specifici del gruppo, revisione su meccanocettori/qualità muscolare senza ricaduta chirurgica diretta) · duplicati di PMID già coperti nei giorni precedenti come schede o brevi (meta-analisi LET già archiviata il 24 agosto, coorte quadricipite/LET già archiviata il 21 agosto, consensus APKASS sulla revisione del LCA già archiviato il 23 agosto, coorte CPAK/HTO già archiviata il 22 agosto, coorte Mako su allineamento femorale e revisione sul valgo grave già archiviate il 25 agosto, studio sullo squat monopodalico a 4 mesi già archiviato il 19 agosto) · studi con rilevanza clinica marginale o non azionabile (bibliometria, survey metodologiche).",nonverificate:["Retraction Watch (archivio salvati vuoto)","pagine ESSKA · AAOS · ICRS (non interrogate direttamente)","registri protesici (SIRIS · RIPO · NJR · AOANJRR)","destino dei verdetti (dipende dal raccoglitore, fermo a ieri)"],nota:"Il raccoglitore notturno è passato regolarmente questa notte (fonti/raccolta.json generato il 26 agosto, 05:17 UTC): nessun richiamo nuovo, nessuna ritrattazione (119 DOI controllati via Crossref), nessun nuovo citante per gli otto PICK sorvegliati. Screening dei contenuti condotto interamente con ricerche dirette su PubMed (datetype=edat): una ricerca generale per termine-nucleo in titolo sulle ultime 24-48 ore, ricerche mirate su LET/tenodesi/Lemaire, radice meniscale, AMIC/cartilagine, VELYS/protesi robotica, slope/osteotomia, MPFL/instabilità rotulea, LCA nell'adolescente, multilegamentose, e consensus/linee guida (finestra 60 giorni), più tre ricerche dedicate «oltre il consueto» su intelligenza artificiale, medicina tradizionale/mondo orientale e bioingegneria/biomeccanica. Circa 55 candidati nuovi distinti esaminati dopo dedup con lo storico: 4 lavori tenuti come schede, 14 come brevi (EXTRA), 3 come proposte fuori dal solito (SCOPERTE: agopuntura sui punti trigger nell'artrosi, magnetoencefalografia e intelligenza artificiale per fenotipizzare il dolore da artrosi, stima del carico articolare con intelligenza artificiale ibrida nella paralisi cerebrale infantile), circa 34 scartati per i motivi sopra. Le ritrattazioni sono state ricontrollate di persona su PubMed per l'intero perimetro citato, storico compreso (88 PMID più i 4 di oggi): zero colpiti."};
var MUTE={2:"Il sottogruppo con LET concomitante (0/18 fallimenti) non può escludere né una forte protezione né un rischio di fallimento quasi decuplicato: RR 0,59, IC 95% 0,04-9,36 (ricalcolato con test/potenza.py).",4:"Caso singolo: nessuna incidenza calcolabile, nessun denominatore — dice che questa complicanza è possibile, non quanto sia frequente."};var TENSIONS=[{id:"1",t:"Il rinforzo laterale (LET) su innesto rigido",fai:"Fai il LET su tutti i pazienti che ricostruisci, con innesto di retto femorale.",prove:"Il beneficio del LET è dimostrato su innesto hamstring. Il protocollo STABILITY 2 scrive testualmente che nessuno studio ha stabilito se quel beneficio resta con innesti più rigidi. Aggiornamento del 12 agosto: un database americano su 5.944 gesti combinati conferma che il tempo unico è sicuro — ma non distingue né il costrutto né l'innesto. Nuovo il 17 agosto: il trial GRASE (Copenaghen, 150 pazienti, reclutamento completo) confronterà i tre innesti, quadricipitale compreso — ma senza LET: risponderà sull'innesto, non sulla tua combinazione. Nuovo il 19 agosto: una piccola serie del gruppo di Bologna (Rizzoli) su 28 pazienti ≥55 anni con LCA over-the-top più LET mostra pochi fallimenti (3,6%) — ma con tecnica femorale diversa dalla tua e innesto non specificato: non tocca la lacuna sull'innesto rigido, aggiunge solo un segnale di sicurezza del LET in età più avanzata. Un trial osservazionale dedicato (NCT07041242, >50 vs <30 anni) è in reclutamento. Nuovo il 21 agosto: una coorte olandese multicentrica su 780 pazienti ≤25 anni mostra che il LET si associa a un rischio di revisione più basso indipendentemente dal grado di slope tibiale (OR 0,37; IC 95% 0,22-0,62) — ma il tipo di innesto è aggiustato come covariata, non stratificato: non conferma che il beneficio si estenda specificamente al tuo tendine quadricipitale/rettofemorale. Nello stesso giorno, una coorte cilena su 268 pazienti suggerisce che il quadricipite recupera forza e spessore più in fretta nei primi 9 mesi quando si aggiunge il LET (vasto intermedio in particolare), ma il confronto statistico diretto fra i due gruppi non è riportato — dato suggestivo, non dimostrato. Due revisioni narrative (Ann Jt, con Alan Getgood; OTSR, con David Dejour) confermano il quadro generale positivo sul LET senza aggiungere dati quantitativi nuovi sul tuo innesto specifico. Nuovo il 23 agosto: il consensus APKASS 2024 (parte II, 23 esperti di 8 paesi) sulla revisione del LCA aggiunge una dimensione mai toccata finora — non l'innesto rigido, ma l'indicazione stessa del LET. Gli esperti lo raccomandano in modo selettivo, «in base ai fattori individuali del paziente», non come gesto automatico su ogni revisione: una filosofia esplicitamente diversa dalla tua indicazione universale su tutti i pazienti operati di LCA. Non è una prova che la tua scelta sia sbagliata — è opinione di esperti, livello V — ma è la prima volta che una fonte autorevole descrive il LET come procedura selettiva anziché sistematica, e lo fa proprio sul terreno della revisione. Sull'innesto per la revisione, gli stessi esperti indicano il tendine osso-rotuleo-osso come prima scelta, con il tendine quadricipitale riconosciuto come alternativa valida, non marginale. Nuovo il 24 agosto 2026, il tassello più diretto finora sulla tua indicazione universale. Una meta-analisi di 10 RCT (11 studi randomizzati, 1.419 pazienti: 725 ACLR+LET, 694 ACLR isolata — la sintesi più ampia mai pubblicata sul tema) conferma il beneficio del LET su fallimento dell'innesto (log OR -1,19; IC 95% -1,73/-0,65; p<0,001) e stabilità rotazionale al pivot shift (log OR -0,81; IC 95% -1,11/-0,52; p<0,001), con guadagni piccoli ma statisticamente significativi su Lysholm (+1,98 punti; IC 95% 0,19-3,77) e IKDC soggettivo (+1,65 punti; IC 95% 0,24-3,05). Nessuna differenza su KT-1000, Lachman, IKDC oggettivo, KOOS, Tegner o ritorno allo sport. Il punto che conta di più: gli stessi autori, alla luce dei propri risultati, concludono per «un uso selettivo e basato sul rischio, particolarmente nei pazienti giovani e ad alta domanda funzionale a rischio di fallimento dell'innesto o di instabilità rotatoria persistente, piuttosto che l'uso di routine in tutti i casi primari di ACLR» — la prima raccomandazione esplicita di livello I contro l'indicazione universale che segui. Non tocca però né il tuo innesto né il tuo costrutto: solo 1 studio su 11 ammetteva il tendine quadricipitale (mescolato al rotuleo, non isolato), il resto è quasi tutto hamstring o osso-tendine-osso, e il 43,6% del campione pooled proviene dal solo trial STABILITY, che usa fissazione profonda con graffa. Nessuna sottoanalisi per tipo di innesto, tecnica o profilo di rischio è stata condotta — dichiarato dagli stessi autori come limite. Nuovo il 26 agosto 2026, un segnale piccolo ma nella tua direzione. Una coorte retrospettiva di 452 ricostruzioni primarie del LCA (Nicholas et al., The Knee) non trova alcun fallimento dell'innesto fra i 18 pazienti che hanno ricevuto anche un LET concomitante (0/18), contro il 4,4% del resto della coorte (19/434). Ricalcolato con `test/potenza.py` sui conteggi grezzi: rischio relativo 0,59, IC 95% 0,04-9,36 — un intervallo che non esclude né una forte protezione né un rischio quasi decuplicato. Non è una dimostrazione, è un segnale muto che va nella direzione della tua pratica; il dato più solido dello studio riguarda un'altra domanda — il diametro dell'innesto, non il costrutto del LET, predice il fallimento in modo indipendente (OR 0,48 per innesto più piccolo; IC 95% 0,23-1,00).",fare:"Non cambiare nulla: non è un errore, è una lacuna della letteratura, e ora anche una differenza di filosofia dichiarata da un gruppo di esperti e, dal 24 agosto, da una meta-analisi di RCT. Ma se un collega ti chiede perché lo fai su tutti, la risposta onesta è: «beneficio dimostrato su hamstring/BPTB — inclusa la sintesi di RCT più ampia oggi disponibile — esteso per ragionevolezza al quadricipitale, con un segnale di beneficio sul rischio di revisione indipendente dallo slope ma non stratificato per innesto, e sia un consensus internazionale sia la meta-analisi di RCT più recente che lo vorrebbero selettivo, non automatico». Nessuna delle due fonti però stratifica per il tuo innesto o il tuo costrutto: resta un giudizio sulla popolazione media studiata, non sulla tua casistica specifica.",chiude:"STABILITY 2, braccio quadricipitale con e senza LET, 1292 pazienti. Risultati attesi nel 2029."},{id:"2",t:"Il tuo costrutto non è quello studiato",fai:"Lemaire modificato, fissazione onlay, passaggio superficiale al collaterale laterale.",prove:"I trial usano il passaggio profondo sotto il collaterale e la fissazione con graffa. Sono due costrutti biomeccanicamente diversi, che la letteratura tratta come se fossero la stessa cosa. Nuovo il 20 agosto: una revisione anatomica sulla bendelletta ileotibiale, con Robert LaPrade fra gli autori, descrive in dettaglio le fibre di Kaplan e la componente capsulo-ossea profonda del sistema anterolaterale — l'anatomia su cui si basa il razionale del LET — ma resta una sintesi narrativa che non distingue esplicitamente il costrutto profondo con graffa da quello onlay superficiale: non chiude la tensione, ne rafforza solo lo sfondo anatomico. Nuovo il 21 agosto: una rassegna storica francese (Favreau, con David Dejour) colloca la ricostruzione anterolaterale fra i contributi francesi diventati standard internazionale, insieme alla conservazione meniscale, ma senza distinguere il costrutto onlay dal profondo con graffa: la conferma come pratica diffusa, non ne risolve il dettaglio tecnico. Nuovo il 24 agosto 2026: la meta-analisi di 10 RCT sul LET che aggiorna anche la T1a non stratifica per costrutto — profondo con graffa vs onlay superficiale — e il 43,6% del campione pooled proviene dal solo trial STABILITY, che usa fissazione a graffa. Non chiude la tensione, la conferma: la base di evidenza resta quella del costrutto profondo, non del tuo.",fare:"Quando leggi i risultati di un trial sul LET, ricorda che non sono automaticamente i tuoi. Segnale a tuo favore: le note tecniche recenti si stanno spostando verso l'onlay — il campo va dove sei tu, le prove non ancora.",chiude:"Un confronto diretto fra i due costrutti. Oggi non esiste, e nemmeno STABILITY 2 lo risolverà."},{id:"3",t:"Nella radice meniscale conta l'estrusione, non il ritardo",fai:"Rifissazione della radice con tecnica transtibiale. Nel colloquio si tende a pesare il grado condrale e il tempo trascorso dall'infortunio.",prove:"All'analisi multivariata il ritardo NON è predittore indipendente di progressione (p=0,31). Lo sono l'estrusione meniscale (p=0,023) e la larghezza dello spazio articolare preoperatoria. La storia naturale (64 radici non operate, 12 agosto): estrusione da 3,1 a 4,3 mm in 6 mesi mentre il dolore migliora; converte a chirurgia chi ha più varo (soglia HKA 5,5°). E l'osteoporosi più che raddoppia il rischio di frattura subcondrale nella donna (OR 2,29). Lo stato dell'arte J ISAKOS del 17 agosto (Pittsburgh, con Seil, Getgood e Karlsson) conferma la transtibiale come tecnica di scelta e aggiunge il dato che pesa: nel trial sulla centralizzazione l'estrusione aumenta a 6 mesi nel 96,2% delle ginocchia, qualunque cosa si faccia. Il 19 agosto: in una coorte AJSM di 115 pazienti dopo sutura della radice, la condrosi femoro-rotulea avanzata al momento dell'intervento (non l'estrusione, ma un altro marcatore di carico degenerativo basale) non peggiora i sintomi a medio termine in chi non fallisce, ma si associa a una conversione a protesi quasi 7 volte più frequente (14,9% vs 2,1%; p=0,021) — un secondo marcatore, accanto all'estrusione, dello stesso principio: conta il carico degenerativo di partenza, non il tempo trascorso. Nuovo il 21 agosto: una coorte francese su 841 ginocchia mostra che combinare la riparazione della radice meniscale (qui laterale, all-inside — non la tua transtibiale mediale) con la ricostruzione del LCA non compromette in modo dimostrato la sopravvivenza dell'innesto, ma il gruppo combinato è piccolo e lo studio non esclude un rischio di ri-rottura fino a quasi 4 volte più alto: un dato rassicurante sul principio generale, muto sul numero esatto. Nuovo il 22 agosto, un terzo marcatore dello stesso principio, questa volta sul lato della soglia operativa: una revisione narrativa sulla necessità di osteotomia concomitante nella riparazione della radice mediale mostra che, nel ginocchio in varo, la riparazione isolata fallisce alla RM nell'88,5% dei casi e la progressione artrosica è 2,37 volte più frequente rispetto all'asse neutro; aggiungere l'osteotomia (soglia proposta: varo ≥5° correggibile) migliora nettamente i risultati.",fare:"AZIONE CONCRETA, da subito: misura e referta l'estrusione sulla risonanza preoperatoria, e usa quella nel colloquio sul rischio di progressione, al posto del grado condrale e del tempo trascorso. Aggiungi l'asse (varo oltre ~5°, soglia rafforzata da una seconda fonte), nella donna la densità ossea, e il grado di condrosi femoro-rotulea osservato in artroscopia: sono gli altri volti del carico basale, e per il varo esiste ora un'indicazione operativa esplicita — considerare l'osteotomia concomitante quando la deviazione è ≥5° e correggibile.",chiude:"Studi prospettici con l'estrusione come variabile principale. Confidenza attuale: media — due retrospettivi piccoli, una coorte prospettica (64 pazienti), due coorti retrospettive (115 e 841 pazienti) e una revisione narrativa (soglia di varo) nella stessa direzione generale, con marcatori diversi."},{id:"4",t:"Il criterio di rientro non regge sul tuo innesto",fai:"Se usi la simmetria di forza al 90% come criterio per il ritorno allo sport.",prove:"Sul retto femorale, a 6 mesi, il deficit di estensione è del 29% (simmetria 71%), mentre la flessione recupera al 93%. Con una soglia del 90% quasi nessuno passa a 6 mesi. Aggiornamento del 18 agosto: uno studio trasversale su 30 operati (1-5 anni dall'intervento, tutti gli innesti) conferma che il deficit dell'arto chirurgico nel salto monopodalico resta misurabile anche a distanza di anni (-1,2 cm rispetto al controlaterale; p<0,01); un carico visivo-cognitivo aggiuntivo non lo aggrava ulteriormente rispetto ai controlli sani — il limite sembra dell'arto, non dell'attenzione. Il 19 agosto, due segnali che si parlano: uno studio prospettico su 53 pazienti mostra che il modo di caricare il ginocchio (il momento di flessione, non il semplice angolo) in uno squat monopodalico a 4 mesi predice la forza e la funzione a 6-12 mesi — un possibile segnale precoce, oltre la sola simmetria di forza a fine percorso. E sul calcio femminile d'élite, 242 infortuni al LCA in 206 giocatrici: il 66,8% torna in campo, ma nel primo anno di rientro il tempo di gioco cala del 47-58% (p<0,001), soprattutto nelle centrocampiste — il ritorno in campo non equivale al ritorno al livello precedente. Nuovo il 21 agosto: la stessa coorte cilena di 268 pazienti che tocca la T1a mostra un possibile beneficio del LET sul recupero della forza e dello spessore del quadricipite nei primi 9 mesi — coerente con l'ipotesi che il criterio di rientro debba tenere conto della componente muscolare, non solo della stabilità legamentosa — ma il confronto statistico diretto fra i due gruppi (con e senza LET) non è riportato nell'abstract: da confermare. Nuovo il 25 agosto 2026, due segnali dalla seconda pagina che allargano il profilo oltre la sola simmetria di forza. Uno studio biomeccanico mostra che aggiungere un carico cognitivo durante l'atterraggio dopo la ricostruzione del LCA modifica la meccanica del salto in modo diverso rispetto a chi non è mai stato operato — un secondo segnale, indipendente da quello del 18 agosto, che il test motorio da solo può non cogliere tutto ciò che conta per il rientro. E uno studio caso-controllo esplora insieme, dopo la ricostruzione, la propriocezione in valgo, l'attività muscolare, gli esiti riferiti dal paziente e il controllo dinamico dell'equilibrio: un profilo più ampio della sola forza, ancora descrittivo, non ancora un criterio di rientro alternativo pronto all'uso.",fare:"Verifica che cosa misuri davvero a 6 mesi. Sul quadricipitale aspettati tempi più lunghi per l'estensione: o sposti la scadenza, o cambi la misura. Considera che un test biomeccanico precoce (4 mesi), non solo la simmetria di forza a fine percorso, potrebbe segnalare prima chi ha bisogno di più tempo — da confermare, non ancora uno strumento pronto. Dato su 31 pazienti, soli maschi, un solo centro.",chiude:"Studi che leghino il deficit di forza a esiti duri (rirottura, mancato rientro) e non a misure intermedie."},{id:"5",t:"Nel minced cartilage varia il tessuto, non solo la tecnica",fai:"Trapianto di cartilagine tritata con filiera dedicata.",prove:"I campioni prelevati da difetti debridati variano oltre dieci volte in peso umido, DNA totale e proteoglicani. Dipende da quale tessuto si raccoglie, non dallo strumento.",fare:"Se un caso va peggio di un altro a parità di gesto chirurgico, la variabile può essere la qualità del tessuto raccolto. Utile saperlo prima di attribuirlo alla tecnica.",chiude:"Una caratterizzazione di vitalità e resa cellulare specifica della filiera che usi. Oggi non esiste."}];
var NLB={
1:{"prof":["PSI vs strumentazione convenzionale in protesi monocompartimentale: nessuna differenza funzionale a 1 anno","Revisione sistematica e metanalisi su 14 studi (5 RCT a basso rischio di bias, 9 studi retrospettivi di confronto, rischio da moderato ad alto in diversi), 1680 ginocchia in 1670 pazienti. L'esito primario, Oxford Knee Score a 1 anno, non mostra differenza significativa tra strumentazione paziente-specifica (PSI) e strumentazione convenzionale: differenza media 0,90 punti, IC 95% da -2,65 a 4,45, I²=0%. Anche gli esiti secondari — Knee Society Score e KOOS a 3 mesi e a ≥12 mesi — non mostrano differenze.","I dati WOMAC erano insufficienti per un pooling quantitativo, e i tassi di revisione troppo eterogenei tra gli studi per essere sommati: sull'effetto della PSI sul rischio di revisione la metanalisi non si esprime."],"mix":["Strumentazione su misura o standard per la protesi mono? A un anno il punteggio funzionale non cambia","Una revisione di 14 studi, quasi 1700 pazienti operati di protesi monocompartimentale di ginocchio, ha confrontato la strumentazione paziente-specifica (guide su misura, realizzate per quel singolo ginocchio) con la strumentazione tradizionale. Il punteggio funzionale principale (Oxford Knee Score), misurato a un anno, è risultato sovrapponibile tra i due gruppi: la piccola differenza osservata non è statisticamente significativa. Anche gli altri punteggi funzionali raccolti a 3 mesi e oltre un anno confermano l'assenza di differenza.","Sul rischio di dover rioperare la protesi lo studio non riesce a dare una risposta, perché i dati raccolti nei vari centri erano troppo diversi tra loro per essere messi insieme in modo affidabile."],"paz":["Guida su misura o strumentazione standard per la protesi parziale di ginocchio: il risultato funzionale è lo stesso","Alcuni interventi di protesi parziale di ginocchio usano una guida di taglio realizzata su misura per quel singolo ginocchio, altri una strumentazione standard riutilizzabile. Un'analisi che ha messo insieme i risultati di quasi 1700 pazienti operati con l'uno o l'altro metodo mostra che, a un anno dall'intervento, il livello di funzione del ginocchio riferito dai pazienti è lo stesso nei due gruppi.","Lo studio non dice se un metodo comporti meno probabilità di dover essere rioperato in futuro: su questo punto i dati raccolti erano troppo diversi da un centro all'altro per trarre una conclusione."],"kw":"protesi ginocchio su misura · guida di taglio personalizzata · protesi parziale ginocchio"},
2:{"prof":["Ampiezza della gola intercondiloidea e fallimento dell'innesto dopo ricostruzione del LCA: non è un fattore di rischio, il diametro dell'innesto sì","Coorte retrospettiva di 452 pazienti sottoposti a ricostruzione primaria del LCA (2012-2024), 19/452 fallimenti dell'innesto (4,2%), definiti come revisione. L'indice di ampiezza della gola intercondiloidea (NWI), misurato su RM coronale preoperatoria con affidabilità interosservatore alta (ICC 0,865), non è risultato associato al fallimento dell'innesto (p=0,237); né il sesso (p=0,483) né il tipo di innesto (p=0,536). Sono risultati associati l'età più giovane (p=0,008) e un diametro dell'innesto tibiale più piccolo (p=0,049). All'analisi multivariata: età più giovane OR 0,91 (IC 95% 0,84-1,00), diametro dell'innesto più piccolo OR 0,48 (IC 95% 0,23-1,00) — entrambi fattori di rischio indipendenti.","Nel sottogruppo con tenodesi extra-articolare laterale (LET) associata (18/452), 0 fallimenti su 18, contro 19/434 (4,4%) nel resto della coorte. Ricalcolando il rischio relativo su questi conteggi grezzi: RR 0,59, IC 95% 0,04-9,36 — un intervallo che non esclude né un forte effetto protettivo né un rischio quasi decuplicato. È un risultato statisticamente muto, non una prova che la LET protegga l'innesto."],"mix":["Non è la larghezza del canale del ginocchio a contare per il rischio di rottura dell'innesto, ma il suo diametro","In 452 pazienti operati di ricostruzione del legamento crociato anteriore, l'innesto si è rotto di nuovo (richiedendo un reintervento) in 19 casi su 452, il 4,2%. I ricercatori hanno misurato con risonanza magnetica l'ampiezza del canale osseo dentro cui passa il legamento (l'indice NWI), con una misurazione affidabile e ripetibile. Questa ampiezza non è risultata legata al rischio di rottura, e nemmeno il sesso del paziente o il tipo di tessuto usato per l'innesto. Due fattori invece contavano: l'età più giovane e un innesto tibiale di diametro più piccolo, entrambi collegati a un rischio più alto di rottura in modo indipendente l'uno dall'altro.","In un piccolo gruppo di 18 pazienti a cui era stato aggiunto un rinforzo laterale (tenodesi extra-articolare, LET), nessuno ha avuto una rottura, contro il 4,4% del resto della coorte. Il numero di pazienti è però troppo piccolo per dire se questo rinforzo protegga davvero l'innesto: il calcolo statistico su questi numeri è troppo incerto per dare una risposta, in un senso o nell'altro."],"paz":["Dopo la ricostruzione del legamento crociato: cosa aumenta davvero il rischio di doverlo rioperare","In uno studio su 452 pazienti operati di ricostruzione del legamento crociato anteriore, in 19 casi su 452 (il 4,2%) è stato necessario un secondo intervento per una nuova rottura dell'innesto. Alcuni fattori che si pensava potessero avere un ruolo — la forma del canale osseo del ginocchio visibile alla risonanza, il sesso, il tipo di tessuto usato per ricostruire il legamento — non sono risultati collegati al rischio. Due fattori invece lo erano: l'età più giovane al momento dell'intervento e un innesto di diametro più piccolo.","Nello studio, un piccolo gruppo di 18 pazienti aveva ricevuto anche un rinforzo laterale del ginocchio: nessuno di loro ha avuto una nuova rottura. Il numero di pazienti in questo gruppo è però troppo piccolo perché questo dato dimostri che il rinforzo protegga: serve prudenza, non conclusioni affrettate."],"kw":"rottura crociato dopo ricostruzione · dimensione innesto ginocchio · reintervento crociato anteriore"},
3:{"prof":["Infezione postoperatoria dopo ricostruzione del LCA: rischio significativamente più alto di artrosi tricompartimentale a lungo termine","Studio caso-controllo retrospettivo: 7 pazienti con infezione postoperatoria dopo ricostruzione primaria del LCA (2003-2014), senza artrosi al basale, confrontati con un gruppo di controllo appaiato senza infezione. Follow-up medio 16,2 anni (range 14-19). Tutti i 7 pazienti infetti (100%) hanno sviluppato artrosi tricompartimentale (Kellgren-Lawrence ≥2), contro il 35% dei controlli (p=0,0058). L'angolo di allineamento hip-knee-ankle non differiva tra i gruppi (4,42° varo negli infetti vs 4,67° varo nei controlli, p=0,77), così come punteggi clinici (IKDC, Lysholm, Tegner), lassità antero-posteriore (KT-1000) e ginocchio controlaterale.","Il campione assoluto è molto piccolo (7 pazienti infetti), monocentrico: la significatività statistica raggiunta (p=0,0058) riflette una dimensione dell'effetto molto ampia, ma la stima resta da leggere con cautela su un numero così ridotto."],"mix":["Un'infezione dopo l'intervento al legamento crociato aumenta il rischio di artrosi a lungo termine, anche a distanza di anni","In uno studio che ha seguito i pazienti per una media di oltre 16 anni dopo l'intervento, tutti e 7 i pazienti che avevano avuto un'infezione dopo la ricostruzione del legamento crociato anteriore hanno sviluppato artrosi in tutti e tre i compartimenti del ginocchio, contro il 35% di un gruppo di confronto senza infezione — una differenza statisticamente significativa. L'allineamento delle gambe non differiva tra i due gruppi, e nemmeno i punteggi clinici di funzione o la stabilità del ginocchio misurata strumentalmente.","Il numero di pazienti con infezione era molto piccolo, solo 7, e lo studio viene da un unico centro: la differenza osservata è statisticamente solida, ma va letta con la cautela che merita un campione così ristretto."],"paz":["Un'infezione dopo l'intervento al legamento crociato può aumentare il rischio di artrosi negli anni successivi","In uno studio che ha seguito i pazienti per una media di più di 16 anni dopo l'intervento, tutti i pazienti che avevano avuto un'infezione dopo la ricostruzione del legamento crociato anteriore hanno sviluppato con il tempo segni di artrosi diffusa nel ginocchio, molto più spesso di chi non aveva avuto l'infezione. Il ginocchio non era diverso per allineamento delle gambe o per i sintomi riferiti a distanza.","I pazienti con infezione osservati in questo studio erano solo 7, in un unico centro: un numero piccolo, anche se la differenza trovata è chiara e affidabile dal punto di vista statistico. È un motivo in più per prendere sul serio la prevenzione e il trattamento tempestivo di un'eventuale infezione dopo questo intervento."],"kw":"infezione dopo ricostruzione crociato · artrosi ginocchio dopo intervento · rischio infezione chirurgia ginocchio"},
4:{"prof":["Osteomielite fungina subacuta dopo riparazione artroscopica della radice meniscale: primo caso descritto","Case report: donna di 70 anni, dolore tibiale subacuto e secrezione recidivante alcuni mesi dopo riparazione della radice del menisco mediale (MRR). RM: ascesso metafisario tipo Brodie con tramite dal portale artroscopico antero-mediale. PCR: Aspergillus versicolor. Trattamento: debridement chirurgico con rimozione della sutura ritenuta, seguito da voriconazolo orale. A 1 anno: nessun segno di infezione residua, ripresa dell'attività fisica senza dolore. Gli autori lo definiscono, per quanto a loro noto, il primo caso riportato di osteomielite fungina dopo MRR.","Si tratta di un singolo caso clinico: non è possibile calcolarne un'incidenza, non esiste un denominatore né un gruppo di confronto. Gli autori segnalano che i pazienti anziani potrebbero avere un rischio più alto di infezioni profonde rare dopo questa procedura, ma resta un'ipotesi da un solo caso."],"mix":["Un'infezione fungina rarissima dopo la riparazione del menisco: un solo caso descritto in letteratura, ma da tenere presente","Una donna di 70 anni ha sviluppato, alcuni mesi dopo un intervento di riparazione della radice del menisco mediale, dolore persistente alla tibia e una perdita di liquido dalla zona dell'intervento. Gli esami hanno mostrato un ascesso osseo collegato al punto d'ingresso dello strumento chirurgico, causato da un fungo, l'Aspergillus versicolor. È stata curata con un intervento di pulizia chirurgica, la rimozione di un filo di sutura rimasto in sede, e una terapia antifungina per via orale. A un anno era guarita, senza segni di infezione, e aveva ripreso l'attività fisica senza dolore.","È un singolo caso, il primo mai descritto di questo tipo di infezione dopo questo intervento: da un solo caso non si può calcolare quanto sia frequente, né fare un confronto con altri pazienti. Gli autori suggeriscono solo che, nei pazienti anziani, vale la pena restare attenti a un dolore persistente e insolito nei mesi successivi all'intervento."],"paz":["Un caso raro di infezione dopo la riparazione del menisco, in una paziente anziana: cosa insegna","Una signora di 70 anni ha avuto, alcuni mesi dopo un intervento al menisco, dolore persistente e una perdita di liquido nella zona operata. Gli accertamenti hanno individuato un'infezione ossea causata da un fungo, molto rara dopo questo tipo di intervento. È stata curata con una pulizia chirurgica e una terapia per via orale, e dopo un anno era completamente guarita, senza dolore e con una normale attività fisica.","Si tratta di un caso isolato, il primo descritto di questo genere: non permette di dire quanto sia comune questo tipo di infezione, che resta un evento raro. È comunque un buon motivo per segnalare al proprio chirurgo un dolore insolito e persistente nei mesi dopo l'intervento, soprattutto in età più avanzata."],"kw":"dolore persistente dopo riparazione menisco · infezione rara dopo artroscopia ginocchio · osteomielite fungina ginocchio"}
};
