var SCOPERTE=[
 {t:"Agopuntura sui punti trigger contro l'agopuntura classica nell'artrosi di ginocchio: uno studio randomizzato cinese",v:"Medicina tradizionale cinese messa alla prova con il metodo occidentale: uno studio randomizzato in singolo cieco su 106 pazienti con artrosi di ginocchio in stadio iniziale-medio confronta l'agopuntura classica con l'aggiunta mirata di aghi sui punti trigger miofasciali. L'esito primario — la percentuale di pazienti che rispondono al trattamento a due settimane — non è risultato significativamente diverso fra i due gruppi (95,9% vs 87,5%; differenza di rischio 8,4 punti percentuali, IC 95% da -2,5 a 19,3; p=0,13), anche se alcune analisi esplorative secondarie hanno favorito l'aggiunta dei punti trigger su dolore e velocità del cammino. Il prezzo: più dolore durante le sedute e un'accettabilità nettamente più bassa (36,7% contro 72,9%) nel gruppo con i punti trigger. Nessun evento avverso serio in nessuno dei due gruppi.",pmid:'42633430',doi:'10.2147/JPR.S634945',temi:["mondo orientale","medicina tradizionale","artrosi"]},
 {t:"Leggere nel cervello il tipo di dolore dell'artrosi: magnetoencefalografia e intelligenza artificiale spiegabile",v:"Intelligenza artificiale in ortopedia, versione neuroscientifica: uno studio cinese su 192 pazienti con artrosi di ginocchio distingue chi ha un dolore di tipo neuropatico (55 pazienti) da chi ha un dolore nocicettivo classico (137 pazienti) misurando l'attività cerebrale con la magnetoencefalografia durante uno stimolo doloroso. Un modello di apprendimento automatico interpretabile, basato su queste onde cerebrali, distingue i due tipi di dolore con un'accuratezza moderata (area sotto la curva ROC 0,768; IC 95% 0,745-0,789). Studio esplorativo, lontanissimo dalla pratica chirurgica quotidiana, ma indica una direzione: il dolore nell'artrosi non è tutto uguale, e un giorno la diagnostica potrebbe distinguerlo prima di scegliere il trattamento.",pmid:'42621580',doi:'10.2147/JPR.S622996',temi:["intelligenza artificiale","neuroscienze","artrosi"]},
 {t:"Stimare la forza sulle articolazioni senza pedana di forza, con un'intelligenza artificiale ibrida",v:"Bioingegneria applicata alla riabilitazione pediatrica: un gruppo di ricerca neozelandese-cinese sviluppa un modello di intelligenza artificiale che stima il momento di forza su anca, ginocchio e caviglia in bambini con paralisi cerebrale usando solo elettromiografia di superficie e angoli articolari, senza la pedana di forza riservata ai laboratori specializzati. Il modello, che combina una rete neurale con un modello biomeccanico classico del muscolo, raggiunge una correlazione di 0,826 con la misura di riferimento — meglio di dodici modelli puramente basati sui dati confrontati nello stesso studio. Campo lontano dalla chirurgia dell'adulto, ma la stessa logica, stimare il carico articolare senza strumentazione da laboratorio, potrebbe un giorno arrivare anche all'analisi del cammino dopo un intervento al ginocchio.",pmid:'42623196',doi:'10.1109/TNSRE.2026.3725088',temi:["intelligenza artificiale","bioingegneria","riabilitazione"]}
];
